INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES
(5122, 'koKR', '$GOdzyskałeś:Odzyskałaś; medalion! Teraz będę mógł opuścić kaplicę i wypełnić swój obowiązek.$B$BA moim obowiązkiem jest zabić bestię, która pomogła splugawić mnie i tak wielu moich braci i sióstr – barona Zerwikrusza!', 0),
(5125, 'koKR', '$N, umieram... ale moja dusza jest ocalona. Zawdzięczam ci więcej, niż mogą wyrazić słowa. Proszę, weź to... i walcz dalej, $gdzielny bohaterze:dzielna bohaterko;!', 0);
INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES
(5122, 'koKR', 'Moc tej kaplicy daje mi siłę, by opierać się skażeniu w moim sercu. Jeśli ją opuszczę, stanę się rycerzem śmierci. Istnieje jednak medalion, Medalion wiary, który da mi siłę potrzebną, by odejść.$B$BProszę, $N, odzyskaj medalion. Strzeże go Malor Gorliwy, obłąkany członek Szkarłatnej Krucjaty, który przebywa w głębi Szkarłatnego Bastionu w zachodnim Stratholmie.', 0);
