INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(5772, 'koKR', '%s pada, ale zmasakrowane ciało znów się podnosi!', '', 0),
(5773, 'koKR', 'Żywi tu są!', '', 0),
(6150, 'koKR', 'TIMMY!', '', 0),
(6162, 'koKR', 'Intruzi przy Bramie Służebnej! Trzeba ostrzec lorda Zerwikrusza!', '', 0),
(6235, 'koKR', 'Dobrze widzieć innych, którzy walczą z Plagą w Stratholmie, bo to tutaj jest ona najsilniejsza.$B$BWitaj. Jestem Aurius. Byłem niegdyś paladynem Srebrnej Dłoni, ale jak inni, których wiara się zachwiała... upadłem. Plaga mnie uwiodła i niemal przemieniła w rycerza śmierci!$B$BGdy w końcu dostrzegłem grożące mi niebezpieczeństwo, uciekłem do tej kaplicy. To święte miejsce, w którym pierwszy paladyn, Uther Światłodzierżca, został wyświęcony na członka zakonu Srebrnej Dłoni.', '', 0),
(6238, 'koKR', 'Nie zostało mi wiele czasu na tym świecie, ale jeśli Światłość pozwoli, wystarczy go, by wypełnić moje przeznaczenie. Gdy staniesz do walki z baronem Zerwikruszem, będę przy tobie.', '', 0),
(6239, 'koKR', 'Zostaw mnie. Moje rany są ciężkie i obawiam się, że mnie pokonają. Dziękuję ci, $n. Umrę tutaj, ale dzięki tobie... umrę w spokoju.', '', 0),
(6257, 'koKR', '%s eksploduje, uwalniając kilka żółciowych szlamów!', '', 0),
(6258, 'koKR', '%s wypluwa obrzydliwy żółciowy szlam!', '', 0),
(6289, 'koKR', 'Kryształy Ash\'ari zostały zniszczone! Rzeźnia jest bezbronna!', '', 0),
(6377, 'koKR', 'Cofnąć się i utrzymać linię! Nie możemy zawieść, bo wszystko przepadnie!', 'Cofnąć się i utrzymać linię! Nie możemy zawieść, bo wszystko przepadnie!', 0),
(6378, 'koKR', 'Na schody i bronić się!', 'Na schody i bronić się!', 0),
(6379, 'koKR', 'Wdarli się do Sali Świateł! Musimy powstrzymać intruzów!', 'Wdarli się do Sali Świateł! Musimy powstrzymać intruzów!\n', 0),
(6380, 'koKR', 'To nie będzie koniec Szkarłatnej Krucjaty! Nie przełamiecie naszej linii!', 'To nie będzie koniec Szkarłatnej Krucjaty! Nie przełamiecie naszej linii!\n', 0),
(6398, 'koKR', 'A więc zachciało wam się zabawiać dziełami Króla Lisza? Ramsteinie, dopilnuj, by intruzi zostali należycie powitani.', '', 0),
(6401, 'koKR', 'Czas wziąć sprawy w swoje ręce. Chodźcie. Wkroczcie do mojej domeny i zmierzcie się z potęgą Plagi!', '', 0),
(6439, 'koKR', 'Plaga przedarła się do wszystkich skrzydeł! Niech Światłość pokona te plugawe stwory! Będziemy walczyć do ostatniego tchu!', 'Plaga przedarła się do wszystkich skrzydeł! Niech Światłość pokona te plugawe stwory! Będziemy walczyć do ostatniego tchu!', 0),
(6441, 'koKR', 'Dziś zniweczyliście to, co tworzyłem latami! Za to wszyscy zginiecie z mojej ręki!', '', 0),
(6442, 'koKR', 'Przeklęci śmiertelnicy! Wszystkie moje plany zemsty, cała moja nienawiść... Zostanę pomszczony...', '', 0),
(6447, 'koKR', 'Głupcy, myślicie, że tak łatwo mnie pokonacie? Poznajcie prawdziwą potęgę nathrezimów!', '', 0),
(6492, 'koKR', 'Jeden z Kryształów Ash\'ari został zniszczony! Zabić intruzów!', 'Jeden z Kryształów Ash\'ari został zniszczony! Zabić intruzów!', 0),
(6511, 'koKR', '%s przywraca do życia nieumarłego sługę!', '', 0),
(6512, 'koKR', '%s próbuje rzucić Pakt śmierci na swoje sługi!', '', 0),
(6526, 'koKR', 'Kryształ Ash\'ari upadł! Pozostańcie wierni Królowi Liszowi, bracia, i spróbujcie przyzwać go ponownie.', 'Kryształ Ash\'ari upadł! Pozostańcie wierni Królowi Liszowi, bracia, i spróbujcie przyzwać go ponownie.', 0),
(6527, 'koKR', 'Kryształ Ash\'ari został obalony! Przywróćcie zigurat, zanim Rzeźnia stanie się bezbronna!', 'Kryształ Ash\'ari został obalony! Przywróćcie zigurat, zanim Rzeźnia stanie się bezbronna!', 0),
(11812, 'koKR', 'Intruzi! Bez wątpienia kolejne pionki Argentowego Brzasku. Jedną z nich już mam wśród swoich więźniów. Wynoście się z mojej domeny, zanim zostanie stracona!', '', 0),
(11813, 'koKR', 'Wciąż tu jesteście? Wasza głupota mnie bawi! Ta dziewka z Argentowego Brzasku nie musi cierpieć na próżno. Odejdźcie natychmiast, a zostanie oszczędzona!', '', 0),
(11814, 'koKR', 'Niech śmierć tej więźniarki będzie ostrzeżeniem. Nikt nie sprzeciwi się Pladze i nie przeżyje!', '', 0),
(11815, 'koKR', 'Z wielką przyjemnością odbiorę życie tej nieszczęsnej! Jeszcze nie jest za późno, nie musi cierpieć na próżno. Zawróćcie, a jej śmierć będzie miłosierna!', '', 0),
(14595, 'koKR', 'Głupcze! Czy wiesz, co $gzrobiłeś:zrobiłaś;? To święta ziemia!', '', 0);
